/**
 * Teacher mic ducking while the share's computer sound plays (B1, live test
 * 2026-10-17). With speakers, the room mic re-captures the video's sound
 * (measured: mic −63 → −31 dBFS, corr 0.15–0.18 with the clip) and students
 * hear it twice: clean on `screen_audio` and again, delayed, on the mic. Echo
 * cancellation cannot remove it: its reference is only this app's playback.
 *
 * Sidechain gate: while computer sound is active (its level above
 * SYS_ACTIVE_DB) the mic is attenuated to DUCK_GAIN, unless the mic is
 * clearly louder than speaker bleed (the teacher is talking over the video:
 * TALK_OVER_DB). Fast attack, slow release with a hold, so words are not
 * chopped and the gate does not flutter.
 */
export const SYS_ACTIVE_DB = -45;
export const TALK_OVER_DB = -24;
export const DUCK_GAIN = 0.1; // −20 dB: speaker bleed falls under the room noise floor
export const HOLD_MS = 350;

export type DuckState = { gain: number; holdUntil: number; ducked: boolean; everDucked: boolean };
export const DUCK_IDLE: DuckState = { gain: 1, holdUntil: 0, ducked: false, everDucked: false };

export function rmsDb(samples: ArrayLike<number>, scale = 1): number {
  let sum = 0;
  const n = samples.length;
  if (!n) return -120;
  for (let i = 0; i < n; i++) {
    const v = samples[i]! / scale;
    sum += v * v;
  }
  const rms = Math.sqrt(sum / n);
  return rms > 0 ? Math.max(-120, 20 * Math.log10(rms)) : -120;
}

/** One control step: system-audio level, mic level (dBFS), now (ms) → next state. */
export function duckStep(prev: DuckState, sysDb: number, micDb: number, now: number): DuckState {
  const sysActive = sysDb > SYS_ACTIVE_DB;
  const talking = micDb > TALK_OVER_DB;
  const wantDuck = sysActive && !talking;
  if (wantDuck) return { gain: DUCK_GAIN, holdUntil: now + HOLD_MS, ducked: true, everDucked: true };
  if (prev.ducked && now < prev.holdUntil) return prev; // hold: no flutter between words / frames
  return { gain: 1, holdUntil: 0, ducked: false, everDucked: prev.everDucked };
}

export const HEADPHONES_HINT =
  "Your computer's sound is reaching your microphone (speakers). Your mic is turned down while it plays; use headphones to talk over videos.";

/**
 * Browser side: a LiveKit audio TrackProcessor that routes the mic through a
 * GainNode (after the browser's echo cancellation / noise suppression, which
 * run in getUserMedia) and measures the mic level. `setGain` is driven by
 * duckStep from the sidechain level.
 */
export class MicDuckProcessor {
  readonly name = 'mic-duck';
  processedTrack?: MediaStreamTrack;
  private ctx: AudioContext | null = null;
  private src: MediaStreamAudioSourceNode | null = null;
  private gain: GainNode | null = null;
  private analyser: AnalyserNode | null = null;
  private buf: Float32Array<ArrayBuffer> | null = null;

  async init(opts: { track: MediaStreamTrack; audioContext: AudioContext }): Promise<void> {
    this.ctx = opts.audioContext;
    this.src = this.ctx.createMediaStreamSource(new MediaStream([opts.track]));
    this.gain = this.ctx.createGain();
    this.analyser = this.ctx.createAnalyser();
    this.analyser.fftSize = 1024;
    this.buf = new Float32Array(this.analyser.fftSize);
    const dest = this.ctx.createMediaStreamDestination();
    this.src.connect(this.analyser);
    this.src.connect(this.gain).connect(dest);
    this.processedTrack = dest.stream.getAudioTracks()[0];
  }

  async restart(opts: { track: MediaStreamTrack; audioContext: AudioContext }): Promise<void> {
    await this.destroy();
    await this.init(opts);
  }

  async destroy(): Promise<void> {
    try {
      this.src?.disconnect();
      this.gain?.disconnect();
    } catch {
      /* already gone */
    }
    this.processedTrack?.stop();
    this.src = this.gain = this.analyser = null;
    this.processedTrack = undefined;
  }

  micDb(): number {
    if (!this.analyser || !this.buf) return -120;
    this.analyser.getFloatTimeDomainData(this.buf);
    return rmsDb(this.buf);
  }

  setGain(g: number): void {
    if (!this.gain || !this.ctx) return;
    // ~10 ms attack when ducking, ~120 ms release.
    this.gain.gain.setTargetAtTime(g, this.ctx.currentTime, g < this.gain.gain.value ? 0.01 : 0.12);
  }
}

/** Level of a local MediaStreamTrack (the share's computer sound in the browser path). */
export function trackLevelMeter(ctx: AudioContext, track: MediaStreamTrack): { db: () => number; stop: () => void } {
  const src = ctx.createMediaStreamSource(new MediaStream([track]));
  const an = ctx.createAnalyser();
  an.fftSize = 1024;
  const buf = new Float32Array(an.fftSize);
  src.connect(an);
  return {
    db: () => {
      an.getFloatTimeDomainData(buf);
      return rmsDb(buf);
    },
    stop: () => {
      try {
        src.disconnect();
      } catch {
        /* gone */
      }
    },
  };
}
